    const list = idx.cells.get(stKey(ix, iz));
    if (!list) continue;
    for (let i = 0; i < list.length; i++) { const s = sol[list[i]]; if (s.top !== undefined) continue; const e = stSegEnter(s, ax, az, dx, dz); if (e < ts) ts = e; }
  }
