10	/* ============================ Cầu Rồng: thân rồng ============================ */
11	export let spine: THREE.CatmullRomCurve3;
12	let spineFrames: { tangents: THREE.Vector3[]; normals: THREE.Vector3[]; binormals: THREE.Vector3[] }, spineLen: number;
13	const SPINE_SEGS = 1400;
14	const spineP: THREE.Vector3[] = [];
15	function spineRadius(u: number) {
16	  const R = CONFIG.bodyRadius;
17	  if (u < 0.06) return lerp(0.25, R, smooth(u / 0.06));
18	  if (u > 0.95) return lerp(R, CONFIG.headRadius, smooth((u - 0.95) / 0.05));
19	  return R;
20	}
21	function spineUp(i: number, out: THREE.Vector3) { // hướng "lên" vuông góc tiếp tuyến
22	  const T = spineFrames.tangents[i];
23	  return out.copy(UP).addScaledVector(T, -T.y).normalize();
24	}
25	export function buildDragonBody() {
26	  const pts: THREE.Vector3[] = [];
