1	import * as THREE from 'three';
2	import { MAT } from '../../core/materials';
3	import { UP } from '../../common/geometry';
4	import { SH, shRoadY } from './profile';
5	import type { SwingController } from './SwingController';
6	import type { SongHanBridge } from './SongHanBridge';
7	
8	/* [lighting] barie + đèn tín hiệu + đèn hàng hải */
9	export function shBuildSignals(bridge: SongHanBridge) {
10	  const M = bridge.mats, bx = SH.barrierX, curb = SH.hw - SH.sidewalk + 0.15;
11	  // 4 barie: mỗi đầu nhịp quay chặn cả hai làn; tay barie quay quanh trụ ở mép lề
12	  bridge.barrierSpec = [];
13	  for (const sx of [-1, 1]) for (const sz of [-1, 1]) bridge.barrierSpec.push({ x: sx * bx, z: sz * curb, sz });
14	  const arm = new THREE.BoxGeometry(0.14, 0.14, curb - SH.median / 2 + 0.1).translate(0, 0, -(curb - SH.median / 2 + 0.1) / 2);
15	  bridge.arms = new THREE.InstancedMesh(arm, M.barrier, 4); bridge.arms.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
16	  const housing = new THREE.InstancedMesh(new THREE.BoxGeometry(0.45, 1.0, 0.45).translate(0, 0.5, 0), M.housing, 4), m = new THREE.Matrix4();
17	  bridge.barrierSpec.forEach((b, i) => housing.setMatrixAt(i, m.makeTranslation(b.x, shRoadY(b.x) + 0.25, b.z)));
18	  bridge.details.add(bridge.arms, housing);
19	  // 4 cột đèn tín hiệu (đỏ / vàng / xanh) đặt trên lề, trước barie theo hướng xe tới
20	  const poles = new THREE.InstancedMesh(new THREE.CylinderGeometry(0.08, 0.1, 4.2, 6).translate(0, 2.1, 0), MAT.lampPole, 4);
21	  const heads = new THREE.InstancedMesh(new THREE.BoxGeometry(0.4, 1.3, 0.4), M.mech, 4);
22	  bridge.signalLamps = new THREE.InstancedMesh(new THREE.SphereGeometry(0.13, 10, 8), M.lamp, 12);
23	  bridge.signalLamps.instanceColor = new THREE.InstancedBufferAttribute(new Float32Array(36), 3);
24	  bridge.barrierSpec.forEach((b, i) => {
25	    const x = b.x - Math.sign(b.x) * 3, z = b.z + b.sz * 1.3, y = shRoadY(x) + 0.25;
26	    poles.setMatrixAt(i, m.makeTranslation(x, y, z)); heads.setMatrixAt(i, m.makeTranslation(x, y + 3.9, z));
27	    for (let j = 0; j < 3; j++) bridge.signalLamps.setMatrixAt(i * 3 + j, m.makeTranslation(x - Math.sign(b.x) * 0.22, y + 4.3 - j * 0.4, z));
28	  });
29	  bridge.details.add(poles, heads, bridge.signalLamps);
30	  // đèn hàng hải trên trụ quay
31	  bridge.pierNav = new THREE.InstancedMesh(new THREE.SphereGeometry(0.35, 10, 8), M.lamp, 2);
32	  bridge.pierNav.setMatrixAt(0, m.makeTranslation(0, SH.drumTop + 0.4, SH.drumR - 0.4));
33	  bridge.pierNav.setMatrixAt(1, m.makeTranslation(0, SH.drumTop + 0.4, -SH.drumR + 0.4));
34	  bridge.pierNav.instanceColor = new THREE.InstancedBufferAttribute(new Float32Array(6), 3);
35	  bridge.details.add(bridge.pierNav);
36	}
37	/* Mọi mesh ở đây nằm trong details / swingDetails: SongHanBridge chỉ gọi khi details hiện (vừa hiện lại thì ghi ngay trong khung đó). Không cấp phát mỗi khung (D-018) */
38	const _m = new THREE.Matrix4(), _q = new THREE.Quaternion(), _qy = new THREE.Quaternion(), _v = new THREE.Vector3(), _one = new THREE.Vector3(1, 1, 1), X_AXIS = new THREE.Vector3(1, 0, 0);
39	const PIN_XZ = [[-1, -2.4], [-1, 2.4], [1, -2.4], [1, 2.4]];
40	const setRgb = (a: Float32Array, o: number, r: number, g: number, b: number) => { a[o] = r; a[o + 1] = g; a[o + 2] = b; };
41	export function shUpdateSignals(bridge: SongHanBridge, ctrl: SwingController, elapsed: number) {
42	  const m = _m, q = _q, qy = _qy, v = _v, one = _one;
43	  const raise = (1 - ctrl.barrier) * THREE.MathUtils.degToRad(84);
44	  q.setFromAxisAngle(X_AXIS, raise);
45	  for (let i = 0; i < bridge.barrierSpec.length; i++) {
46	    const b = bridge.barrierSpec[i];
47	    qy.setFromAxisAngle(UP, b.sz > 0 ? 0 : Math.PI).multiply(q);
48	    bridge.arms.setMatrixAt(i, m.compose(v.set(b.x, shRoadY(b.x) + 1.15, b.z), qy, one));
49	  }
50	  bridge.arms.instanceMatrix.needsUpdate = true;
51	  const blink = (elapsed % 1) < 0.5, c = bridge.signalLamps.instanceColor.array as Float32Array;
