9	export function shBuildSignals(bridge: SongHanBridge) {
10	  const M = bridge.mats, bx = SH.barrierX, curb = SH.hw - SH.sidewalk + 0.15;
11	  // 4 barie: mỗi đầu nhịp quay chặn cả hai làn; tay barie quay quanh trụ ở mép lề
