41	export function shUpdateSignals(bridge: SongHanBridge, ctrl: SwingController, elapsed: number) {
42	  const m = _m, q = _q, qy = _qy, v = _v, one = _one;
43	  const raise = (1 - ctrl.barrier) * THREE.MathUtils.degToRad(84);
44	  q.setFromAxisAngle(X_AXIS, raise);
45	  for (let i = 0; i < bridge.barrierSpec.length; i++) {
