64	  for (let i = 0; i < 2; i++) { if (!moving) setRgb(pc, i * 3, 1.6, 1.6, 1.4); else if (blink) setRgb(pc, i * 3, 3, 1.6, 0.1); else setRgb(pc, i * 3, 0.2, 0.1, 0); }
