10	/* mulberry32 riêng: map test không kéo three vào */
11	function mulberry(seed: number) { return () => { seed |= 0; seed = seed + 0x6D2B79F5 | 0; let t = Math.imul(seed ^ seed >>> 15, 1 | seed); t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t; return ((t ^ t >>> 14) >>> 0) / 4294967296; }; }
12	
13	const HOUSE: StSolid = { kind: 'rect', x0: 10, x1: 24, z0: -5, z1: 5 };          // nhà dày 14 m theo x
14	const COLUMN: StSolid = { kind: 'circle', cx: -20, cz: 0, r: 1 };                 // cột tròn
15	const LOW: StSolid = { kind: 'rect', x0: -40, x1: -39.7, z0: -15, z1: 15, top: 0.9 };   // tường thấp 0,9 m
16	
17	function makeZones(): StZone[] {
18	  return [
19	    { id: 'A', x0: -50, x1: 0, z0: -20, z1: 20, y: () => 2.5 },
20	    { id: 'B', x0: 0, x1: 50, z0: -20, z1: 20, y: (x) => 2.6 + x * 0.001 },
21	    { id: 'G', x0: 50, x1: 60, z0: -5, z1: 5, y: () => 3, gate: 'span' },
22	  ];
23	}
24	function makeMap(): StMap { return stMakeMap(makeZones(), [HOUSE, COLUMN, LOW], R); }
25	
