const node = (x: number, z: number) => (z - B.z0) * NX + (x - B.x0);
function bfs(m: StMap, sx: number, sz: number, box = { x0: B.x0, x1: B.x1, z0: B.z0, z1: B.z1 }): Uint8Array {
